import{_ as s,o as i,c as a,a2 as e}from"./chunks/framework.YT-FC_Xx.js";const u=JSON.parse('{"title":"分流规则与链式代理","description":"","frontmatter":{},"headers":[],"relativePath":"guide/subscription-rules.md","filePath":"guide/subscription-rules.md","lastUpdated":1792732097000}'),o={name:"guide/subscription-rules.md"};function r(l,t,d,n,h,p){return i(),a("div",null,[...t[0]||(t[0]=[e(`<h1 id="分流规则与链式代理" tabindex="-1">分流规则与链式代理 <a class="header-anchor" href="#分流规则与链式代理" aria-label="Permalink to &quot;分流规则与链式代理&quot;">​</a></h1><p>都在编辑订阅的 <strong>规则</strong> 页设置，影响客户端拿到的配置。想完全按自己的规则和策略组来，见 <a href="./subscription-templates">订阅模板</a>。</p><h2 id="分流规则" tabindex="-1">分流规则 <a class="header-anchor" href="#分流规则" aria-label="Permalink to &quot;分流规则&quot;">​</a></h2><p>默认生成的配置只有“局域网直连、其余走节点选择”两条规则。在订阅的 <strong>分流规则</strong> 里打开后，Clash（mihomo）、sing-box、Surge、Shadowrocket、Loon 和 Quantumult X 的配置会带上：</p><ul><li><strong>基础规则</strong>：局域网和国内域名 / IP 走“全球直连”，境外网站走“节点选择”，剩下的走“漏网之鱼”</li><li><strong>勾选的分组</strong>：每组是一个可单独选节点的策略组</li></ul><table tabindex="0"><thead><tr><th>分组</th><th>默认</th><th>包含</th></tr></thead><tbody><tr><td>广告拦截</td><td>拦截</td><td>常见广告域名（sing-box 里直接拦截，没有可切换的组）</td></tr><tr><td>AI 服务</td><td>美国地区组</td><td>OpenAI、Claude、Gemini 及其他境外 AI</td></tr><tr><td>YouTube</td><td>节点选择</td><td>YouTube</td></tr><tr><td>Netflix</td><td>节点选择</td><td>Netflix</td></tr><tr><td>国外媒体</td><td>节点选择</td><td>Disney+、Spotify、TikTok</td></tr><tr><td>Telegram</td><td>节点选择</td><td>Telegram</td></tr><tr><td>Google</td><td>节点选择</td><td>Google</td></tr><tr><td>微软服务</td><td>直连</td><td>微软、OneDrive（GitHub 仍走节点选择）</td></tr><tr><td>苹果服务</td><td>直连</td><td>Apple</td></tr><tr><td>游戏平台</td><td>直连</td><td>Steam 等游戏平台（国内 CDN 始终直连）</td></tr></tbody></table><ul><li>打开后自动按地区分组，每个分组都能直接选地区；没有美国节点时，AI 服务默认走节点选择</li><li>Clash 和 sing-box 还会带上 DNS：国内域名用阿里 / 腾讯 DoH 解析，其余经节点用 Google / Cloudflare DoH 解析，避免 DNS 泄漏；Clash 另开启 fake-ip 和域名嗅探</li><li>规则集是 GitHub 上的远程文件，客户端定期自动更新：Clash 用 <a href="https://github.com/MetaCubeX/meta-rules-dat" target="_blank" rel="noreferrer">MetaCubeX/meta-rules-dat</a> 的 <code>.mrs</code>，sing-box 用同一仓库的 <code>.srs</code>，Surge、Shadowrocket、Loon、Quantumult X 用 <a href="https://github.com/blackmatrix7/ios_rule_script" target="_blank" rel="noreferrer">blackmatrix7/ios_rule_script</a> 里对应客户端的规则</li><li>Clash 和 sing-box 经“节点选择”下载规则集，在国内也能下载；其余客户端自己下载规则集，网络连不上 GitHub 时规则会暂时缺失</li><li><strong>Shadowrocket、Loon、Quantumult X 的节点订阅无法携带规则和策略组</strong>，所以开启后这三个客户端的链接改为下发 <strong>完整配置</strong>（节点直接写在配置里），导入会替换 App 里原来的配置，原来作为节点订阅导入的需要重新导入： <ul><li>Shadowrocket：Clash 格式的配置，点客户端直接导入（<code>shadowrocket://config/add/</code>）</li><li>Loon / Quantumult X：复制链接，在 App 的配置管理里“从 URL 下载”</li><li>链式代理：Shadowrocket 照旧生成“落地（经 中转）”节点；Loon 和 Quantumult X 没有前置代理参数，落地节点仍是直连</li></ul></li><li><code>.mrs</code> 只有 mihomo 内核能读：Stash 订阅的规则集改用 YAML 格式（同一套规则），也不带 mihomo 专用的 DNS / 嗅探设置；已停更的 Clash Premium / Clash for Windows 原版内核不支持</li></ul><h2 id="链式代理" tabindex="-1">链式代理 <a class="header-anchor" href="#链式代理" aria-label="Permalink to &quot;链式代理&quot;">​</a></h2><p>让客户端先连 <strong>中转节点</strong>，再经它连 <strong>落地节点</strong>，网站看到的是落地节点的 IP。适合“国内 → 香港中转 → 美国落地”这类线路，或者给机场节点套一层自己的落地。</p><p>在编辑订阅的 <strong>规则</strong> 页展开 <strong>链式代理</strong>，先 <strong>按来源</strong> 设置，再 <strong>按节点</strong> 单独调整：</p><ul><li><strong>自建节点都作为落地</strong>：面板上自己的节点（含它们的中转线路）都是出口</li><li><strong>订阅源</strong>：整个源点 <strong>不用 / 落地 / 中转</strong>。机场节点做前置时选“中转”，以后机场改名（比如倍率变了）、增删节点都会自动跟上，不用重新勾选。这里只列出订阅所选节点组里有节点的订阅源：链式代理只给组里的节点分配角色，不会再加节点进来，想用某个订阅源就先把它选进节点组</li><li><strong>名称筛选</strong>：订阅源设成落地或中转后，可以只用名称匹配的节点，写法和过滤一样：关键词用 <code>|</code> 分隔（如 <code>香港|日本</code>），或 <code>/正则/</code>（如 <code>/IEPL|IPLC/</code>）。按机场的原名匹配，机场改名、新增节点只要还匹配就自动跟上；没匹配上的节点不参与链式代理</li><li><strong>没用上的节点不放进订阅</strong>：链式代理里的订阅源，没筛选上或单独设成“不用”的节点直接不进订阅；不影响其他来源</li><li><strong>中转节点不单独列出</strong>：中转节点只出现在“中转节点”组里，不混进节点选择、自动选择和地区组（模板里取全部节点的组也会去掉它们）</li><li><strong>按节点</strong>：列表里是这个订阅所选节点组的所有节点，点 <strong>不用 / 落地 / 中转</strong> 单独设置，优先于来源设置；比如机场整个作中转，但把某个节点设成“不用”</li></ul><p>订阅源的 <a href="./subscription-sources#订阅源">用途</a> 设成“中转”或“落地”后，新建订阅会按用途自动设好上面这些。</p><p>角色的作用：</p><ul><li><strong>落地节点</strong>：挂上中转组，即 Clash / Mihomo 的 <code>dialer-proxy</code>、sing-box 的 <code>detour</code>、Surge 的 <code>underlying-proxy</code></li><li><strong>中转节点</strong>：放进“中转节点”组</li></ul><p>生成的订阅里多两个分组：</p><table tabindex="0"><thead><tr><th>分组</th><th>说明</th></tr></thead><tbody><tr><td>落地节点</td><td>选出口，排在“节点选择”的第一个</td></tr><tr><td>中转节点</td><td>选中转，所有落地节点都经这里选中的节点连接</td></tr></tbody></table><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">proxies</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;美国 落地 01&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">vless</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # ...</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    dialer-proxy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;中转节点&quot;</span></span></code></pre></div><ul><li>落地和中转都至少选一个才生效；页面顶部会显示“已开启”</li><li>按节点设置记的是节点原名，之后改名、加国旗不影响；节点被删掉或改了原名需要重新勾选（按订阅源设置的不受影响）</li><li>旧版本用名称表达式设置的链式代理照常生效，页面上会提示；在列表里重新勾选后改用勾选结果</li><li>预览里会标出“落地”“中转”</li><li>落地节点仍可在“节点选择”和地区分组里直接选，选中后同样经中转连接；中转节点也可以单独使用</li><li>通用分享链接（Base64）无法表达链式，落地节点在里面是直连</li><li>延迟叠加，速度取决于最慢的一段；落地是 Hysteria2 / TUIC 等 UDP 协议时，中转节点要能转发 UDP</li></ul><blockquote><p>这是客户端侧的链式。想让服务器自己把流量转到另一个节点出去（客户端无感），用入站的 <a href="./routing">分流与链式出站</a>。</p></blockquote>`,19)])])}const c=s(o,[["render",r]]);export{u as __pageData,c as default};
